<?php require 'config/database.php';require 'partials/functions.php';$id=(int)($_GET['id']??0);$st=$conn->prepare('SELECT * FROM products WHERE id=?');$st->bind_param('i',$id);$st->execute();$p=$st->get_result()->fetch_assoc();if($p&&$p['stock']>0){$price=final_price($p);if(isset($_SESSION['cart'][$id]))$_SESSION['cart'][$id]['qty']++;else $_SESSION['cart'][$id]=['id'=>$id,'name'=>$p['name'],'price'=>$price,'qty'=>1,'image'=>$p['image'],'stock'=>$p['stock']];}header('Location: cart.php');
